CREATE VIEW Vue_MultiPrcs as 
select ExporterName,Rtrim(a.DocNo)+'/'+ Rtrim(a.Finyear) GRN_NO,GRNDate,Pname,IsNull(Trs_Del1.DocNo,0) as DocNo,PartyDcRef,  Rtrim(OrderMas.Jobno)+'/'+Rtrim(orderMas.Finyear) IONo, Deptname,IsNull(DesignDesc,'')DesignDesc,CountName,Fabdesc,ColorDesc,SubProcess,Mas_Dia.Dia,b.DcKgs,b.DcMtr,  b.RecKgs,b.Recmtr, Mas_Dia1.Dia as FinDia, Mas_Dia1.Dia as PrgKnitDia,PrgKnitGsm,FinGsm,GG,LL,Dt,Mas_Dept.DeptID,Mas_Party.PID PartyId,OrderMas.OrdId,RowSlno,  Rtrim(isnull(Trs_Del1.Docno,''
))+ '/' + trs_del1.Finyear as DCNo,a.ProcessType from Trs_MultiPrs_Grn1 a inner join Trs_MultiPrs_Grn3 B ON A.id =B.ID inner join   Trs_MultiPrs_Grn2 c ON a.id = c.id  and b.DeptID = c.DeptID and b.SubPrsId= c.SubPrsId  INNER JOIN StockTAble D ON B.StockID = D.StockID and B.Ordid = D.Ordid inner join   mas_fabric on mas_fabric.fabid=D.fabid inner join mas_color on mas_color.colid=D.colid inner join Mas_Count on Mas_Count.CountID=D.CntID inner join Mas_Dia on   Mas_Dia.DiaID=D.DiaID inner join Mas_Dept on 
Mas_Dept.DeptID=B.DeptID inner join Mas_Dia Mas_Dia1 on Mas_Dia1.DiaID=D.FinDiaID inner join mas_dia as mas_dia2 on   mas_dia2.DiaID =D.PrgKnitDiaId left join Trs_Del1 on Trs_Del1.id=C.OurDCID inner join Mas_Party on Mas_Party.PID=c.PartyID inner join OrderMas on   OrderMas.OrdId=B.ordid inner join Mas_SubProcess on Mas_SubProcess.ID=b.SubPrsId left join Mas_Design on Mas_Design.DesignId=c.DesignID inner join Mas_Exporter on  Mas_Exporter.ExpID = a.Coycode where c.FinalProcess ='N'
union 
select ExporterName,Rtrim(Trs_Grn1.DocNo)+'/'+ Rtrim(Trs_Grn1.Finyear) GRN_NO,GRNDate,Pname,IsNull(Trs_Del1.DocNo,0) as DocNo,Trs_Grn1.PartyDcRef,  Rtrim(OrderMas.Jobno)+'/'+Rtrim(orderMas.Finyear) IONo, Deptname,IsNull(DesignDesc,'')DesignDesc,CountName,Fabdesc,ColorDesc,SubProcess,Mas_Dia.Dia,b.DcKgs,b.DcMtr,  b.RecKgs,b.Recmtr, Mas_Dia1.Dia as FinDia, Mas_Dia1.Dia as PrgKnitDia,PrgKnitGsm,FinGsm,GG,LL,Trs_Grn1.Dt,Mas_Dept.DeptID,Mas_Party.PID PartyId,OrderMas.OrdId,RowSlno,  Rtrim(isnull(Trs_Del1.Docno,''
))+ '/' + trs_del1.Finyear as DCNo,a.ProcessType from Trs_MultiPrs_Grn1 a inner join Trs_MultiPrs_Grn3 B ON A.id =B.ID inner join   Trs_MultiPrs_Grn2 c ON a.id = c.id   INNER JOIN StockTAble D ON B.StockID = D.StockID and B.Ordid = D.Ordid inner join   mas_fabric on mas_fabric.fabid=D.fabid inner join mas_color on mas_color.colid=D.colid inner join Mas_Count on Mas_Count.CountID=D.CntID inner join Mas_Dia on   Mas_Dia.DiaID=D.DiaID inner join Mas_Dept on 
Mas_Dept.DeptID=B.DeptID inner join Mas_Dia Mas_Dia1 on Mas_Dia1.DiaID=D.FinDiaID inner join mas_dia as mas_dia2 on   mas_dia2.DiaID =D.PrgKnitDiaId left join Trs_Del1 on Trs_Del1.id=C.OurDCID inner join Mas_Party on Mas_Party.PID=c.PartyID inner join OrderMas on   OrderMas.OrdId=B.ordid inner join Mas_SubProcess on Mas_SubProcess.ID=b.SubPrsId left join Mas_Design on Mas_Design.DesignId=c.DesignID inner join Mas_Exporter on  Mas_Exporter.ExpID = a.Coycode inner join Trs_Grn1 on trs_grn1.External_GRNID=c.id and c.DeptID = Trs_Grn1.Dept inner join Trs_Grn2 on Trs_Grn2.ID=Trs_Grn1.ID and Trs_Grn2.StockID= D.StockID  where c.FinalProcess ='Y'